window.MG_LAZY_DATA["data/lazy/resources/security-v26-087-0cb35ac871e69198.json"]={sha256:"0cb35ac871e69198b4a001c78c58bd6c4af7731b05f02e54b5a04034da08023b",value:{"sources":[{"id":"v26-case-f53ed62dd159700c","url":"https://csrc.nist.gov/pubs/sp/800/61/r3/final","title":"NIST SP 800-61r3: incident response and risk management","titleEn":"NIST SP 800-61r3: incident response and risk management","publisher":"NIST","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-087","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-087","related":[{"id":"security-v26-088","referenceUrls":["https://docs.velociraptor.app/docs/clients/artifacts/"],"title":"Velociraptor：最小蒐集與鑑識負載預算","titleEn":"Velociraptor: minimal collection and forensic load budgets","why":"用兩課的可觀察驗收條件比較模型邊界：交付四時間點、決策紀錄、未確定清單、交接模板與瓶頸改善試驗。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver four timestamps, decision log, uncertainty list, handoff template and bottleneck improvement experiment.","difference":"定義問題、必要artifact、範圍、時間窗與資料量上限，記錄collection ID及工具版本。","differenceEn":"Define investigative question, necessary artifacts, scope, time window and volume caps, recording collection ID and tool version.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["端到端回應時間是相鄰階段耗時之和；只縮短確認時間未必改善主要瓶頸。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成事件10:00偵測、10:08確認、10:23完成初步分流、10:50批准隔離。 各階段8、15、27分鐘，總計50分鐘；最長是決策交接27分鐘。","理想傳輸下界=總資料/有效頻寬；另加固定蒐集準備時間，不能混用MB與MiB。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 20台合成主機每台150MB，串行準備各2秒，共用有效傳輸50MB/秒；使用十進位MB。 資料3000MB，傳輸下界60秒，準備40秒，簡化總下界100秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["End-to-end response time sums stage durations; faster acknowledgment may not fix the dominant bottleneck. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A synthetic event is detected at 10:00, acknowledged at 10:08, triaged at 10:23 and approved for isolation at 10:50. Stages take eight, fifteen and twenty-seven minutes, totaling fifty; decision handoff is longest.","Ideal transfer lower bound is total data divided by effective bandwidth; add setup time separately and distinguish MB from MiB. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Twenty synthetic hosts each produce 150 decimal MB, with two seconds of serial setup each and shared effective transfer of 50 MB/s. Data totals 3000 MB; transfer lower bound is sixty seconds plus forty seconds setup, totaling one hundred seconds.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-097","referenceUrls":["https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lock.html"],"title":"S3 Object Lock：版本保留與不可變備份邊界","titleEn":"S3 Object Lock: version retention and immutable-backup boundaries","why":"用兩課的可觀察驗收條件比較模型邊界：交付四時間點、決策紀錄、未確定清單、交接模板與瓶頸改善試驗。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver four timestamps, decision log, uncertainty list, handoff template and bottleneck improvement experiment.","difference":"分清物件key、version ID、保留到期、模式與legal hold，辨識新版本並不覆寫已鎖定舊版本。","differenceEn":"Separate key, version ID, retain-until, mode and legal hold; new versions do not overwrite protected prior versions.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["端到端回應時間是相鄰階段耗時之和；只縮短確認時間未必改善主要瓶頸。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成事件10:00偵測、10:08確認、10:23完成初步分流、10:50批准隔離。 各階段8、15、27分鐘，總計50分鐘；最長是決策交接27分鐘。","固定保留容量估算=每日新增不可變資料×保留天數；版本與重複備份會增加容量，鎖定不等於已驗證可復原。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 每日新增2GB合成備份版本，固定保留30天，假設無壓縮與去重。 穩態最低保留量2×30=60GB，不含額外副本與中繼資料。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["End-to-end response time sums stage durations; faster acknowledgment may not fix the dominant bottleneck. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A synthetic event is detected at 10:00, acknowledged at 10:08, triaged at 10:23 and approved for isolation at 10:50. Stages take eight, fifteen and twenty-seven minutes, totaling fifty; decision handoff is longest.","Fixed-retention capacity is new immutable data per day times days; versions add storage, and locking does not prove recoverability. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Two GB of synthetic backup versions are added daily with thirty-day fixed retention and no compression or deduplication. Steady-state retained data is at least 60 GB, excluding extra copies and metadata.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-e833f3b2aaa060ff","url":"https://docs.velociraptor.app/docs/clients/artifacts/","title":"Velociraptor artifact collections","titleEn":"Velociraptor artifact collections","publisher":"Velociraptor","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-b105a845c1ae4f9e","url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lock.html","title":"Amazon S3 Object Lock","titleEn":"Amazon S3 Object Lock","publisher":"AWS","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
